   387→            .controller
   388→            .is_sidecars_construction_started(&block_root)
   389→        {
   390→            // Request remaining missing data column sidecars from P2P
   391→            let missing_indices = missing_columns_indices
   392→                .into_iter()
   393→                .filter(|index| {
   394→                    !self
   395→                        .received_data_column_sidecars
   396→                        .contains_key(&DataColumnIdentifier {
   397→                            block_root,
   398→                            index: *index,
   399→                        })
   400→                })
   401→                .collect::<Vec<_>>();
